from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class NrcellParamsGenerator(ManagedObject):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.cell_ent = self.enb_ent_config['cells'][self.cell_num]

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        self.set_parameter('lcrId', self.mo_num)
        self.set_parameter('physCellId', self.cell_ent['pci'])
        self.set_parameter('freqBandIndicatorNR', self.cell_ent['freq_band'])
        self.set_parameter('ssbScs', self.cell_ent['scs'])
        self.set_parameter('dlMimoMode', self.cell_ent['dl_mimo_mode'])

        if self.cell_ent['is_fdd']:
            self.set_parameter('cellTechnology', 'FDD')
        else:
            self.set_parameter('cellTechnology', 'TDD')
            self.set_parameter('chBw', self.cell_ent['ch_bw'])
            self.set_parameter('nrarfcn', self.cell_ent['earfcn'])

        if 'nr_cell_type' in self.cell_ent:
            if execution_config['release'] < 25.3 and self.cell_ent['nr_cell_type'] == '16DL8UL':
                self.set_parameter('nrCellType', '16DL4UL')
            else:
                self.set_parameter('nrCellType', self.cell_ent['nr_cell_type'])
        else:
            self.set_parameter('nrCellType', '4DL2UL')

        if 'number_of_rx_beamforming' in self.cell_ent:
            self.set_parameter('numberOfRxBeamforming', self.cell_ent['number_of_rx_beamforming'])

        self.set_optional(execution_config)
        self.set_params_for_ecpri_version()

