    def set_params_for_ecpri_version(self):
        if self.is_ecpri_72a(self.mo_num):
            self.set_params_for_ecpri72a()
        else:
            self.set_params_for_ecpri72e()

    def set_params_for_ecpri72a(self):
        self.log(f"NRCELL[{self.mo_num}]: Setting params for ECPRI version 7.2a")
        self.set_struct_parameter('beamSet', [
            {
                'basicBeamSet': 'beamSet_6',
                'leftEdgeAngle': '60',
                'nrBtsBeamRefinementP2': 'false',
                'rightEdgeAngle': '60',
            },
        ])

    def set_params_for_ecpri72e(self):
        self.log(f"NRCELL[{self.mo_num}]: Setting params for ECPRI version 7.2e")
        self.set_parameter('actEcpri72e', 'true')
        self.set_parameter('numberOfRxPucch', '8Rx')
        self.set_optional_for_ecpri72e()

